/**
 * Shared types for ArkPeak.
 *
 * The Go structs in `internal/town/types.go` are the source of truth. Wails
 * v3 generates TypeScript bindings for them by static analysis, and this
 * module re-exports those generated types so the rest of the frontend never
 * has to know the generated file's long, module-path-derived location.
 *
 * If you change a Go struct's fields, run `wails3 generate bindings` (the
 * `wails3 dev` task does this automatically) and the types below update with
 * it. The hand-written unions at the bottom cannot be generated by Wails, so
 * they live here and are kept in sync with the ruleset by hand.
 */

// The generated bindings live under frontend/bindings/<module path>/. The
// import path is generated from the Go module path, so it is declared once
// here rather than repeated across the frontend.
import type {
  Cell,
  GridDiff,
  TileInfo,
  TownSnapshot,
} from "../bindings/github.com/incurl/arkpeak/internal/town/models";

export type { Cell, GridDiff, TileInfo, TownSnapshot };

/**
 * The tile types ArkPeak knows about.
 *
 * These must match the tile ids in `internal/town/rules/town_rules.json`.
 * The backend sends the authoritative list in `TownSnapshot.tiles`, which is
 * what the UI uses to build its palette; this union exists to give the
 * compiler a closed set for switch statements.
 */
export type TileType =
  | "empty"
  | "floor"
  | "garden"
  | "stairs"
  | "wall"
  | "window"
  | "arch"
  | "roof"
  | "roof_edge"
  | "tower"
  | "spire";

/**
 * The colours the player can paint with.
 *
 * Kept in sync with the palette in `frontend/src/render/palette.ts`.
 */
export type ColorName =
  | ""
  | "sand"
  | "cream"
  | "rose"
  | "sage"
  | "slate"
  | "terracotta";

/** A cell position, matching the Go `wfc.CellKey`. */
export interface CellKey {
  readonly q: number;
  readonly r: number;
  readonly layer: number;
}

/** Builds a CellKey from its parts. */
export function cellKey(q: number, r: number, layer: number): CellKey {
  return { q, r, layer };
}

/** The tile a cell currently holds, or "empty" if it is not settled. */
export function tileOf(cell: Cell | undefined): TileType {
  if (cell === undefined) {
    return "empty";
  }
  return cell.tile as TileType;
}
